// Current state of the operation.
type OperationStatus string

const (
	OperationStatusPending  OperationStatus = "pending"
	OperationStatusComplete OperationStatus = "complete"
	OperationStatusFailed   OperationStatus = "failed"
)

// AllValues returns all OperationStatus values.
func (OperationStatus) AllValues() []OperationStatus {
	return []OperationStatus{
		OperationStatusPending,
		OperationStatusComplete,
		OperationStatusFailed,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s OperationStatus) MarshalText() ([]byte, error) {
	switch s {
	case OperationStatusPending:
		return []byte(s), nil
	case OperationStatusComplete:
		return []byte(s), nil
	case OperationStatusFailed:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *OperationStatus) UnmarshalText(data []byte) error {
	switch OperationStatus(data) {
	case OperationStatusPending:
		*s = OperationStatusPending
		return nil
	case OperationStatusComplete:
		*s = OperationStatusComplete
		return nil
	case OperationStatusFailed:
		*s = OperationStatusFailed
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

